#ifndef _EPDF_H_
#define _EPDF_H_ _EPDF_H_
#include "config.h"
#include <glib.h>
#include <poppler.h>
#include <png.h>

/* Some library functions print warnings to stdout, inhibit it. */
#define DISCARD_STDOUT(saved_fd)                \
  do {                                          \
    int __fd;                                   \
    fflush(stdout);                             \
    saved_fd = dup(1);                          \
    __fd = open("/dev/null", O_WRONLY);         \
    dup2(__fd, 1);                              \
    close(__fd);                                \
  } while (0)

#define UNDISCARD_STDOUT(saved_fd)              \
  do {                                          \
    fflush(stdout);                             \
    dup2(saved_fd, 1);                          \
    close(saved_fd);                            \
  } while (0)

/* Writing responses */
#define OK_BEGIN()                              \
  do {                                          \
    puts("OK");                                 \
  } while (0)

#define OK_END()                                \
  do {                                          \
    puts(".");                                  \
    fflush (stdout);                            \
  } while (0)

#define OK()                                    \
  do {                                          \
    puts ("OK\n.");                             \
    fflush (stdout);                            \
  } while (0)

/* Dealing with image data. */
#ifdef WORDS_BIGENDIAN
#define ARGB_TO_RGB(rgb, argb)                  \
  do {                                          \
    rgb[0] = argb[1];                           \
    rgb[1] = argb[2];                           \
    rgb[2] = argb[3];                           \
  } while (0)

#define ARGB_EQUAL(argb1, argb2)                \
  (argb1[1] == argb2[1]                         \
   && argb1[2] == argb2[2]                      \
   && argb1[3] == argb2[3])

#else
#define ARGB_TO_RGB(rgb, argb)                  \
  do {                                          \
    rgb[0] = argb[2];                           \
    rgb[1] = argb[1];                           \
    rgb[2] = argb[0];                           \
  } while (0)

#define ARGB_EQUAL(argb1, argb2)                \
  (argb1[0] == argb2[0]                         \
   && argb1[1] == argb2[1]                      \
   && argb1[2] == argb2[2])
#endif

#define NORMALIZE_PAGE_ARG(doc, first, last)                    \
  *first = MAX(1, *first);                                      \
  if (*last <= 0)                                               \
    *last = poppler_document_get_n_pages (doc);                 \
  else                                                          \
    *last = MIN(*last, poppler_document_get_n_pages (doc));

/* png_jmpbuf is supposed to be not available in older versions of
   libpng. */
#ifndef png_jmpbuf
#  define png_jmpbuf(png_ptr) ((png_ptr)->jmpbuf)
#endif

#ifndef HAVE_ERROR_H
#  define error(status, errno, fmt, args...)                    \
  do {                                                          \
    int error = (errno);                                        \
    fflush (stdout);                                            \
    fprintf (stderr, "%s: " fmt, PACKAGE_NAME, ## args);        \
    if (error)                                                  \
      fprintf (stderr, ": %s", strerror (error));               \
    fprintf (stderr, "\n");                                     \
    exit (status);                                              \
  } while (0)
#endif

#define internal_error(fmt, args...)                            \
  error (2, 0, "internal error in %s: " fmt, __func__, ## args)

#define error_if_not(expr)                      \
  if (! (expr)) goto error;

#define perror_if_not(expr, fmt, args...)       \
  do {                                          \
    if (! (expr))                               \
      {                                         \
