    gpio_init(23);               // GPIO23 sets the Operating mode of the
    gpio_set_dir(23, GPIO_OUT);  // power supply. A 1 => PWM mode which
    gpio_put(23, 1);             // improves ripple but might lower
}                                // efficiency at light loads


////////////////////////////////////////////////////////////////////////
