void ay_resetay(AYSongInfo * info, int chipnum) {

	if (!chipnum)

		ay_init(&info->chip0);

	else

		ay_init(&info->chip1);

}



void ay_writeay(AYSongInfo * info, int reg, int val, int chipnum) {

	if (!chipnum)

		ay_out(&info->chip0, reg, val);

	else

		ay_out(&info->chip1, reg, val);

}



