		if (PT3_B.Note_Skip_Counter == 0)

			PT3_PatternIntterpreter(info, &PT3_B, chip_num);

		PT3_C.Note_Skip_Counter--;

		if (PT3_C.Note_Skip_Counter == 0)

			PT3_PatternIntterpreter(info, &PT3_C, chip_num);

		PT3.DelayCounter = PT3.Delay;

	}



