void explicit_memzero(void * const pnt, const size_t len)
{
#if defined(HAVE_MEMSET_S)
	if (memset_s(pnt, (rsize_t) len, 0, (rsize_t) len) != 0) {
		abort();
	}
#elif defined(HAVE_EXPLICIT_BZERO)
	explicit_bzero(pnt, len);
#elif HAVE_WEAK_SYMBOLS
	memset(pnt, 0, len);
	_dummy_symbol_to_prevent_lto(pnt, len);
#else
	volatile unsigned char *pnt_ = (volatile unsigned char *) pnt;
	size_t i = (size_t) 0U;
	while (i < len) {
		pnt_[i++] = 0U;
	}
#endif
}


void
randombytes(unsigned char *buf, uint64_t len)
{
#ifdef HAVE_GETRANDOM
	if (getrandom(buf, len, 0) == -1) {
		abort();
	}
#elif defined(HAVE_ARC4RANDOM_BUF)
	arc4random_buf(buf, len);
#elif defined(HAVE_OPENSSL)
	if (RAND_bytes(buf, len) != 1) {
		abort();
	}
#else
	int fd;
	struct stat st;

	fd = open("/dev/urandom", O_RDONLY);

	if (fd == -1 || fstat(fd, &st) == -1 || !S_ISCHR(st.st_mode)) {
		abort();
	}

	if (read(fd, buf, len) != len) {
		abort();
	}

	close(fd);
#endif
}


FILE *
xfopen(const char *fname, const char *mode)
{
	struct stat sb;
	FILE *res = NULL;

	if (fname == NULL || mode == NULL) {
		return (NULL);
	}

	if (strcmp(fname, "-") == 0) {
		if (strchr(mode, 'w') != NULL) {
			return (stdout);
		}
		else {
			return (stdin);
		}
	}
	else {
		if (stat(fname, &sb) == -1) {
			if (strchr(mode, 'w') != NULL) {
				res = fopen(fname, mode);
			}
			else {
				return (NULL);
			}
		}
		else if (S_ISDIR(sb.st_mode)) {
			errno = EINVAL;
		}
		else {
			res = fopen(fname, mode);
		}
	}

	return (res);
}

int
xopen(const char *fname, int oflags, mode_t mode)
{
	struct stat sb;
	int fd;

	if (strcmp(fname, "-") == 0) {
		if ((oflags & O_WRONLY)) {
			fd = dup(STDOUT_FILENO);
		}
		else {
			fd = dup(STDIN_FILENO);
		}
		if (fd == -1) {
			return (-1);
		}
	}
	else {
#ifdef HAVE_O_NOFOLLOW
		fd = open(fname, oflags | O_NOFOLLOW, mode);
#else
		fd = open(fname, oflags, mode);
#endif

		if (fd == -1) {
			return (-1);
		}
	}

	if (fstat(fd, &sb) == -1 || S_ISDIR(sb.st_mode)) {
		close(fd);
		return (-1);
	}

	return (fd);
}

void *
xmalloc(size_t len)
{
	void *p;

	if (len >= SIZE_MAX / 2) {
		abort();
	}

	if (!(p = malloc(len))) {
		abort();
	}
	return (p);
}

void *
xmalloc0(size_t len)
{
	void *p = xmalloc(len);

	memset(p, 0, len);

	return (p);
}

void *
xmalloc_aligned(size_t align, size_t len)
{
	void *p;
	unsigned int v = (unsigned int)len;

	v--;
	v |= v >> 1;
	v |= v >> 2;
	v |= v >> 4;
	v |= v >> 8;
	v |= v >> 16;
	v++;

	if (align > len || len >= UINT32_MAX / 2 || (v & (v - 1)) != 0) {
		abort();
	}

#ifdef HAVE_POSIX_MEMALIGN
	if ((posix_memalign(&p, align, v))) {
		abort();
	}
#elif defined(HAVE_ALIGNED_ALLOC)
	if (!(p = aligned_alloc(align, v))) {
		abort();
	}
#else
#warning No aligned alloc function found
	if (!(p = malloc(v))) {
		abort();
	}
#endif
	return (p);
}

char *
xstrdup(const char *str)
{
	char *p;

	if (!(p = strdup(str))) {
		abort();
	}

	return (p);
}

const char *
xerr_string(enum asignify_error code)
{
