	return (err_str[code]);
}

/* Derived from original code by CodesInChaos */

int
hex2bin(unsigned char * const bin, const size_t bin_maxlen,
    const char * const hex, const size_t hex_len,
    size_t * const bin_len, const char ** const hex_end)
{
	size_t bin_pos = (size_t) 0U;
	size_t hex_pos = (size_t) 0U;
	int ret = 0;
	unsigned char c;
	unsigned char c_acc = 0U;
	unsigned char c_num;
	unsigned char c_val;
	unsigned char state = 0U;

	while (hex_pos < hex_len) {
		c = (unsigned char) hex[hex_pos];
		if ((c_num = c ^ 48U) < 10U) {
			c_val = c_num;
		}
		else if ((c_num = (c & ~32U)) > 64 && c_num < 71U) {
			c_val = c_num - 55U;
		}
		else {
			break;
		}
		if (bin_pos >= bin_maxlen) {
			ret = -1;
			errno = ERANGE;
			break;
		}
		if (state == 0U) {
			c_acc = c_val * 16U;
		}
		else {
			bin[bin_pos++] = c_acc | c_val;
		}
		state = ~state;
		hex_pos++;
	}

	if (state != 0U) {
		hex_pos--;
	}

	if (hex_end != NULL) {
		*hex_end = &hex[hex_pos];
	}

	if (bin_len != NULL) {
		*bin_len = bin_pos;
	}

	return ret;
}

char *
bin2hex(char * const hex, const size_t hex_maxlen,
               const unsigned char * const bin, const size_t bin_len)
{
    size_t       i = (size_t) 0U;
    unsigned int x;
    int          b;
    int          c;

    if (bin_len >= SIZE_MAX / 2 || hex_maxlen < bin_len * 2U) {
        abort();
    }
    while (i < bin_len) {
        c = bin[i] & 0xf;
        b = bin[i] >> 4;
        x = (unsigned char) (87 + c + (((c - 10) >> 31) & -39)) << 8 |
            (unsigned char) (87 + b + (((b - 10) >> 31) & -39));
        hex[i * 2U] = (char) x;
        x >>= 8;
        hex[i * 2U + 1U] = (char) x;
        i++;
    }
    hex[i * 2U] = 0;

    return hex;
}

unsigned int
asignify_digest_len(enum asignify_digest_type type)
{

	if (type >= nitems(digest_lens)) {
		return (0);
	}
	return (digest_lens[type]);
}

const char *
asignify_digest_name(enum asignify_digest_type type)
{
	const char *ret;

	if (type >= nitems(digest_names) || (ret = digest_names[type]) == NULL) {
		return ("");
	}

	return (ret);
}

static void *
asignify_digest_init(enum asignify_digest_type type)
{
#ifdef HAVE_OPENSSL
	EVP_MD_CTX *mdctx;
#else
	SHA2_CTX *st;
#endif
	blake2b_state *bst;

	void *res = NULL;

	switch(type) {
	case ASIGNIFY_DIGEST_SHA512:
#ifdef HAVE_OPENSSL
		mdctx = EVP_MD_CTX_create();
		EVP_DigestInit_ex(mdctx, EVP_sha512(), NULL);
		res = mdctx;
#else
		st = xmalloc(sizeof(*st));
		SHA512Init(st);
		res = st;
#endif
		break;
	case ASIGNIFY_DIGEST_SHA256:
#ifdef HAVE_OPENSSL
		mdctx = EVP_MD_CTX_create();
		EVP_DigestInit(mdctx, EVP_sha256());
		res = mdctx;
#else
		st = xmalloc(sizeof(*st));
		SHA256Init(st);
		res = st;
#endif
		break;
	case ASIGNIFY_DIGEST_BLAKE2:
		bst = xmalloc_aligned(64, sizeof(*bst));
		blake2b_init(bst, BLAKE2B_OUTBYTES);
		res = bst;
		break;
	default:
		abort();
		break;
	}

	return (res);
}

static void
asignify_digest_free(enum asignify_digest_type type, void *res)
{

	switch (type) {
	case ASIGNIFY_DIGEST_BLAKE2:
		free(res);
		break;
	default:
#ifdef HAVE_OPENSSL
		EVP_MD_CTX_free(res);
#else
		free(res);
#endif
		break;
	}
}

static void
asignify_digest_update(enum asignify_digest_type type, void *ctx,
	const unsigned char *buf, size_t len)
{
#ifdef HAVE_OPENSSL
	EVP_MD_CTX *mdctx;
#else
	SHA2_CTX *st;
#endif
	blake2b_state *bst;

	switch(type) {
		case ASIGNIFY_DIGEST_SHA512:
#ifdef HAVE_OPENSSL
			mdctx = (EVP_MD_CTX *)ctx;
			EVP_DigestUpdate(mdctx, buf, len);
#else
			st = (SHA2_CTX *)ctx;
			SHA512Update(st, buf, len);
#endif
			break;
		case ASIGNIFY_DIGEST_SHA256:
#ifdef HAVE_OPENSSL
			mdctx = (EVP_MD_CTX *)ctx;
			EVP_DigestUpdate(mdctx, buf, len);
#else
			st = (SHA2_CTX *)ctx;
			SHA256Update(st, buf, len);
#endif
			break;
		case ASIGNIFY_DIGEST_BLAKE2:
			bst = (blake2b_state *)ctx;
			blake2b_update(bst, buf, len);
			break;
		default:
			abort();
			break;
	}

}

static unsigned char*
asignify_digest_final(enum asignify_digest_type type, void *ctx)
{
	unsigned int len = asignify_digest_len(type);
	unsigned char *res;
#ifdef HAVE_OPENSSL
	EVP_MD_CTX *mdctx;
#else
	SHA2_CTX *st;
#endif
	blake2b_state *bst;

	res = xmalloc(len);
	switch(type) {
		case ASIGNIFY_DIGEST_SHA512:
#ifdef HAVE_OPENSSL
			mdctx = (EVP_MD_CTX *)ctx;
			EVP_DigestFinal(mdctx, res, &len);
#else
			st = (SHA2_CTX *)ctx;
			SHA512Final(res, st);
#endif
			break;
		case ASIGNIFY_DIGEST_SHA256:
#ifdef HAVE_OPENSSL
			mdctx = (EVP_MD_CTX *)ctx;
			EVP_DigestFinal(mdctx, res, &len);
#else
			st = (SHA2_CTX *)ctx;
			SHA256Final(res, st);
#endif
			break;
		case ASIGNIFY_DIGEST_BLAKE2:
			bst = (blake2b_state *)ctx;
			blake2b_final(bst, res, len);
			break;
		default:
			abort();
			break;
	}

	asignify_digest_free(type, ctx);
	return (res);
}

unsigned char*
asignify_digest_fd(enum asignify_digest_type type, int fd)
{
	int r;
#if BUFSIZ >= 2048
	unsigned char buf[BUFSIZ];
#else
	/* BUFSIZ is insanely small */
	unsigned char buf[4096];
#endif
	void *dgst;

	if (fd == -1 || type >= ASIGNIFY_DIGEST_SIZE ||
			(dgst = asignify_digest_init(type)) == NULL) {
		return (NULL);
	}

	if (lseek(fd, 0, SEEK_SET) == (off_t)-1) {
		asignify_digest_free(type, dgst);
		return (NULL);
	}

	while ((r = read(fd, buf, sizeof(buf))) > 0) {
		asignify_digest_update(type, dgst, buf, r);
	}

	return (asignify_digest_final(type, dgst));
}

