void set_blocking(int fd)
{
    int val;

    if ((val = fcntl(fd, F_GETFL)) == -1)
            return;
    if (val & O_NONBLOCK) {
        val &= ~O_NONBLOCK;
        fcntl(fd, F_SETFL, val);
    }
};

void set_nonblocking(int fd)
{
    int val;

    if ((val = fcntl(fd, F_GETFL)) == -1)
            return;
    if (!(val & O_NONBLOCK)) {
        val |= O_NONBLOCK;
        fcntl(fd, F_SETFL, val);
    }
};

