static void drawmenu(struct Menu *menu, struct Slice *selected)
{
    struct Slice *slice;
    Drawable pixmap;
    Picture picture;
    Picture source;
    Picture fg;

    if (selected) {
        pixmap = selected->pixmap;
        picture = selected->picture;
        fg = pie.colors[SCHEME_SELECT][COLOR_FG].pict;
        selected->drawn = 1;
    } else {
        pixmap = menu->pixmap;
        picture = menu->picture;
        fg = pie.colors[SCHEME_NORMAL][COLOR_FG].pict;
        menu->drawn = 1;
    }

    XRenderComposite(
        pie.display,
        PictOpSrc,
        pie.gradient,
        None,
        picture,
        0, 0,
        0, 0,
        0, 0,
        pie.fulldiameter,
        pie.fulldiameter
    );
    drawslice(
        picture,
        pie.colors[SCHEME_NORMAL][COLOR_BG].pict,
        1,
        0,
        0,
        pie.radius
    );
    if (selected != NULL) {
        drawslice(
            picture,
            pie.colors[SCHEME_SELECT][COLOR_BG].pict,
            menu->nslices,
            selected->slicen,
            pie.separatorbeg,
            pie.radius
        );
    }

    /* draw slice foreground */
    for (slice = menu->list; slice; slice = slice->next) {
        if (slice == selected) {
            source = pie.colors[SCHEME_SELECT][COLOR_FG].pict;
        } else {
            source = pie.colors[SCHEME_NORMAL][COLOR_FG].pict;
        }

        if (slice->icon != NULL) {
            imlib_context_set_drawable(pixmap);
            imlib_context_set_image(slice->icon);
            imlib_render_image_on_drawable(slice->iconx, slice->icony);
        } else {
            ctrlfnt_draw(
                pie.fontset,
                picture,
                fg,
                (XRectangle){
                    .x = slice->labelx,
                    .y = slice->labely,
                    .width = pie.radius,
                    .height = pie.fonth,
                },
                slice->label,
                strlen(slice->label)
            );
        }

        /* draw separator */
        drawseparator(picture, menu, slice);

        /* draw triangle */
        if (slice->submenu || slice->iscmd) {
            drawtriangle(source, picture, menu, slice);
        }
    }
}

