void ssd1306_display_text_with_border(SSD1306_t * dev, int page, char * text, int text_len, bool invert, uint8_t border_color)
{
    ssd1306_display_text(dev, page, text, text_len, invert);
    // Draw border around the text
    int start_seg = page * 8;
    int end_seg = start_seg + text_len * 8;
    for (int seg = start_seg; seg < end_seg; seg++) {
        _ssd1306_pixel(dev, seg, page * 8, border_color);
        _ssd1306_pixel(dev, seg, (page + 1) * 8 - 1, border_color);
    }
    for (int line = page * 8; line < (page + 1) * 8; line++) {
        _ssd1306_pixel(dev, start_seg, line, border_color);
        _ssd1306_pixel(dev, end_seg - 1, line, border_color);
    }
}

