int randomize(void){
	int min = 33;
	int max = 126;
	return min + rand() / (RAND_MAX / (max - min + 1) + 1);
}

unsigned char *generateIV(void){
	unsigned char *ivinternal = (unsigned char *)malloc(17);

	for (int i = 0; i < 16; i++){
		ivinternal[i] = randomize();
	}

	ivinternal[16] = '\0';

	return ivinternal;
}

