{
	if (page_ref_sub_and_test(page, count)) {
		unsigned int order = compound_order(page);

                // TODO optimize with free_unref_page
		// if (order == 0)
		// 	free_unref_page(page);
		// else
			__free_pages(page, order);
	}
}
