        for (i = 0; i < adapter->num_tx_queues; i++) {
            sprintf(p, "tx_queue_%u_packets", i);
            p += ETH_GSTRING_LEN;
            sprintf(p, "tx_queue_%u_bytes", i);
            p += ETH_GSTRING_LEN;
            sprintf(p, "tx_queue_%u_restart", i);
            p += ETH_GSTRING_LEN;
        }
        for (i = 0; i < adapter->num_rx_queues; i++) {
            sprintf(p, "rx_queue_%u_packets", i);
