            p += ETH_GSTRING_LEN;
            sprintf(p, "rx_queue_%u_alloc_failed", i);
            p += ETH_GSTRING_LEN;
        }
        break;
    case ETH_SS_PRIV_FLAGS:
        memcpy(data, igc_priv_flags_strings,
               IGC_PRIV_FLAGS_STR_LEN * ETH_GSTRING_LEN);
        break;
    }
}

