:/*
 * coru, a small coroutine library
 *
 * Copyright (c) 2019 Christopher Haster
 * Distributed under the MIT license
 */
#ifndef CORU_H
#define CORU_H

#ifdef __cplusplus
extern "C" {
#endif

#include "coru_util.h"


// Possible error codes, these are negative to allow
// valid positive return values
enum coru_error {
    CORU_ERR_OK     = 0,    // No error
    CORU_ERR_AGAIN  = -11,  // Try again
    CORU_ERR_NOMEM  = -12,  // Out of memory
    CORU_ERR_INVAL  = -22,  // Invalid parameter
};

typedef struct coru {
    void *sp;           // stack information
    uintptr_t *canary;  // canary location, NULL if not supported
    void *allocated;    // buffer if allocated, NULL if user provided
} coru_t;


// Create a coroutine, dynamically allocating memory for the stack
int coru_create(coru_t *coru, void (*cb)(void*), void *data, size_t size);

// Create a coroutine using the provided buffer to store the stack
int coru_create_inplace(coru_t *coru,
        void (*cb)(void*), void *data,
        void *buffer, size_t size);

// Cleans up any resources dedicated to the coroutine
void coru_destroy(coru_t *coru);

// Resume a coroutine
//
// This either proceeds from the last call to yield, or starts the coroutine if
// it has not been started yet
//
// Returns CORU_ERR_EAGAIN if the coroutine does not complete during this call.
// If the coroutine completes during this call, or had already completed, 0 is
// returned.
int coru_resume(coru_t *coru);

// Yields from inside a running coroutine.
//
// Note if not in coroutine this is a noop, this allows yields to be used in
// functions shared between coroutine and non-coroutine code.
void coru_yield(void);


#ifdef __cplusplus
}
#endif

#endif

'coru/coru_platform.h'
:/*
 * coru, platform specific functions
 *
 * Copyright (c) 2019 Christopher Haster
 * Distributed under the MIT license
 *
 * Each platform needs a small bit of custom code for coroutines because
 * of the stack manipulation. Fortunately it only takes two functions. These
 * should be added to coru_platform.c.
 */
#ifndef CORU_PLATFORM_H
#define CORU_PLATFORM_H

#include "coru.h"


// Initialize a coroutine stack
//
// This should set up the stack so that two things happen:
// 1. On the first call to coru_plat_yield, the callback cb should be called
//    with the data argument.
// 2. After the callback cb returns, the coroutine should then transfer control
//    to coru_halt, which does not return.
//
// After coru_plat_init, sp should contain the stack pointer for the new
// coroutine. Also, canary can be set to the end of the stack to enable best
// effort stack checking. Highly suggested.
//
// Any other platform initializations or assertions can be carried out here.
int coru_plat_init(void **sp, uintptr_t **canary,
        void (*cb)(void*), void *data,
        void *buffer, size_t size);

// Yield a coroutine
//
// This is where the magic happens.
//
// Several things must happen:
// 1. Store any callee saved registers/state
// 2. Store arg in temporary register
// 3. Swap sp and stack pointer, must store old stack pointer in sp
// 4. Return arg from temporary register
//
// Looking at the i386 implementation may be helpful
uintptr_t coru_plat_yield(void **sp, uintptr_t arg);


#endif

