  private:
    struct TypePair
    {
        TypePair(const char *l, const char *r)
            : lType(l), rType(r) { }

        const char *lType;
        const char *rType;
    };

    struct TypePairComparator
    {
        bool operator() (const TypePair& l, const TypePair& r) const
        {
