{
	Task *t;

	USED(stack);
	t = taskevent();
	if(t == nil)
		abort();
	memset(t, 0, sizeof *t);
	memmove(t->name, "new task", sizeof("new task"));
	memmove(t->state, "ready", sizeof("ready"));
	t->startfn = fn;
	t->startarg = arg;
