#Modify void init_graphics() {
    // Initialize SDL_ttf for text rendering
    if (TTF_Init() == -1) {
        fprintf(stderr, "TTF_Init: %s\n", TTF_GetError());
        exit(2);
    }

    // Initialize SDL_image for image loading
    int imgFlags = IMG_INIT_PNG;
    if (!(IMG_Init(imgFlags) & imgFlags)) {
        fprintf(stderr, "SDL_image could not initialize! SDL_image Error: %s\n", IMG_GetError());
        exit(2);
    }

    // Create window
    window = SDL_CreateWindow("Tetris", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (window == NULL) {
        fprintf(stderr, "Window could not be created! SDL_Error: %s\n", SDL_GetError());
        exit(2);
    }

    // Create renderer
    render = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (render == NULL) {
        fprintf(stderr, "Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
        exit(2);
    }

    // Load font
    gFont = TTF_OpenFont("path/to/font.ttf", 28);
    if (gFont == NULL) {
        fprintf(stderr, "Failed to load font! SDL_ttf Error: %s\n", TTF_GetError());
        exit(2);
    }

    // Create display texture
    display = SDL_CreateTexture(render, SDL_PIXELFORMAT_RGBA8888, SDL_TEXTUREACCESS_TARGET, SCREEN_WIDTH, SCREEN_HEIGHT);
    if (display == NULL) {
        fprintf(stderr, "Texture could not be created! SDL_Error: %s\n", SDL_GetError());
        exit(2);
    }

    // Display welcome message
    display_welcome_message();
}

#New void display_welcome_message() {
    SDL_Color textColor = {255, 255, 255, 255};
    SDL_Surface* surfaceMessage = TTF_RenderText_Solid(gFont, "Welcome to Tetris!", textColor);
    SDL_Texture* message = SDL_CreateTextureFromSurface(render, surfaceMessage);

    SDL_Rect messageRect;
    messageRect.x = SCREEN_WIDTH / 2 - surfaceMessage->w / 2;
    messageRect.y = SCREEN_HEIGHT / 2 - surfaceMessage->h / 2;
    messageRect.w = surfaceMessage->w;
    messageRect.h = surfaceMessage->h;

    SDL_RenderCopy(render, message, NULL, &messageRect);
    SDL_RenderPresent(render);

    SDL_FreeSurface(surfaceMessage);
    SDL_DestroyTexture(message);
}

