{
    VL53L1_Error Status = VL53L1_ERROR_NONE;
    uint8_t Mm1Enabled = 0;
    uint8_t Mm2Enabled = 0;
    uint32_t  MmTimeoutUs = 0;
    uint32_t  RangeTimeoutUs = 0;
    uint32_t  MeasTimingBdg = 0;
    uint32_t PhaseCalTimeoutUs = 0;
    VL53L1_PresetModes PresetMode;
    uint32_t TimingGuard;
    uint32_t vhv;
    int32_t vhv_loops;

    LOG_FUNCTION_START("");

    *pMeasurementTimingBudgetMicroSeconds = 0;

    if (Status == VL53L1_ERROR_NONE) Status = VL53L1_GetSequenceStepEnable(Dev, VL53L1_SEQUENCESTEP_MM1, &Mm1Enabled);
    if (Status == VL53L1_ERROR_NONE) Status = VL53L1_GetSequenceStepEnable(Dev, VL53L1_SEQUENCESTEP_MM2, &Mm2Enabled);
    if (Status == VL53L1_ERROR_NONE) Status = VL53L1_get_timeouts_us(Dev, &PhaseCalTimeoutUs, &MmTimeoutUs, &RangeTimeoutUs);

    if (Status == VL53L1_ERROR_NONE) {
        PresetMode = VL53L1DevDataGet(Dev, CurrentParameters.PresetMode);

        switch (PresetMode) {
        case VL53L1_PRESETMODE_LITE_RANGING:
            if ((Mm1Enabled == 1) || (Mm2Enabled == 1)) MeasTimingBdg = RangeTimeoutUs + 5000;
            else MeasTimingBdg = RangeTimeoutUs + 1000;
        break;

        case VL53L1_PRESETMODE_AUTONOMOUS:
            if ((Mm1Enabled == 1) || (Mm2Enabled == 1)) MeasTimingBdg = 2 * RangeTimeoutUs + 26600;
            else MeasTimingBdg = 2 * RangeTimeoutUs + 21600;
        break;

        case VL53L1_PRESETMODE_LOWPOWER_AUTONOMOUS:
            vhv = LOWPOWER_AUTO_VHV_LOOP_DURATION_US;
            VL53L1_get_tuning_parm(Dev, VL53L1_TUNINGPARM_LOWPOWERAUTO_VHV_LOOP_BOUND, &vhv_loops);
            if (vhv_loops > 0) {
                vhv += vhv_loops * LOWPOWER_AUTO_VHV_LOOP_DURATION_US;
            }
            TimingGuard = LOWPOWER_AUTO_OVERHEAD_BEFORE_A_RANGING + LOWPOWER_AUTO_OVERHEAD_BETWEEN_A_B_RANGING + vhv;
            MeasTimingBdg = 2 * RangeTimeoutUs + TimingGuard;
        break;

        default:
            Status = VL53L1_ERROR_MODE_NOT_SUPPORTED;
        }
    }
    if (Status == VL53L1_ERROR_NONE) *pMeasurementTimingBudgetMicroSeconds = MeasTimingBdg;

    LOG_FUNCTION_END(Status);
    return Status;
}

