VL53L1_Error VL53L1_SetMeasurementTimingBudgetMicroSeconds(VL53L1_DEV Dev, uint32_t MeasurementTimingBudgetMicroSeconds, uint8_t environmentalCondition) #Modify
{
    VL53L1_Error Status = VL53L1_ERROR_NONE;
    uint8_t Mm1Enabled;
    uint8_t Mm2Enabled;
    uint32_t TimingGuard;
    uint32_t divisor;
    uint32_t TimingBudget;
    uint32_t MmTimeoutUs;
    VL53L1_PresetModes PresetMode;
    uint32_t PhaseCalTimeoutUs;
    uint32_t vhv;
    int32_t vhv_loops;
    uint32_t FDAMaxTimingBudgetUs = FDA_MAX_TIMING_BUDGET_US;

    LOG_FUNCTION_START("");

    if (MeasurementTimingBudgetMicroSeconds > 10000000) Status = VL53L1_ERROR_INVALID_PARAMS;

    if (Status == VL53L1_ERROR_NONE) {
        Status = VL53L1_GetSequenceStepEnable(Dev, VL53L1_SEQUENCESTEP_MM1, &Mm1Enabled);
    }
    if (Status == VL53L1_ERROR_NONE) {
        Status = VL53L1_GetSequenceStepEnable(Dev, VL53L1_SEQUENCESTEP_MM2, &Mm2Enabled);
    }
    if (Status == VL53L1_ERROR_NONE) Status = VL53L1_get_timeouts_us(Dev, &PhaseCalTimeoutUs, &MmTimeoutUs, &TimingBudget);

    if (Status == VL53L1_ERROR_NONE) {
        PresetMode = VL53L1DevDataGet(Dev, CurrentParameters.PresetMode);

        TimingGuard = 0;
        divisor = 1;
        switch (PresetMode) {
        case VL53L1_PRESETMODE_LITE_RANGING:
            if ((Mm1Enabled == 1) || (Mm2Enabled == 1)) TimingGuard = 5000;
            else TimingGuard = 1000;
        break;

        case VL53L1_PRESETMODE_AUTONOMOUS:
            FDAMaxTimingBudgetUs *= 2;
            if ((Mm1Enabled == 1) || (Mm2Enabled == 1)) TimingGuard = 26600;
            else TimingGuard = 21600;
            divisor = 2;
        break;

        case VL53L1_PRESETMODE_LOWPOWER_AUTONOMOUS:
            FDAMaxTimingBudgetUs *= 2;
            vhv = LOWPOWER_AUTO_VHV_LOOP_DURATION_US;
            VL53L1_get_tuning_parm(Dev, VL53L1_TUNINGPARM_LOWPOWERAUTO_VHV_LOOP_BOUND, &vhv_loops);
            if (vhv_loops > 0) {
                vhv += vhv_loops * LOWPOWER_AUTO_VHV_LOOP_DURATION_US;
            }
            TimingGuard = LOWPOWER_AUTO_OVERHEAD_BEFORE_A_RANGING + LOWPOWER_AUTO_OVERHEAD_BETWEEN_A_B_RANGING + vhv;
            divisor = 2;
        break;

        default:
            Status = VL53L1_ERROR_MODE_NOT_SUPPORTED;
        }

        if (MeasurementTimingBudgetMicroSeconds <= TimingGuard) Status = VL53L1_ERROR_INVALID_PARAMS;
        else {
            TimingBudget = (MeasurementTimingBudgetMicroSeconds - TimingGuard);
        }

        if (Status == VL53L1_ERROR_NONE) {
            if (TimingBudget > FDAMaxTimingBudgetUs) Status = VL53L1_ERROR_INVALID_PARAMS;
            else {
                TimingBudget /= divisor;
                Status = VL53L1_set_timeouts_us(Dev, PhaseCalTimeoutUs, MmTimeoutUs, TimingBudget);
            }

            if (Status == VL53L1_ERROR_NONE) VL53L1DevDataSet(Dev, LLData.range_config_timeout_us, TimingBudget);
        }
    }
    if (Status == VL53L1_ERROR_NONE) {
        VL53L1DevDataSet(Dev, CurrentParameters.MeasurementTimingBudgetMicroSeconds, MeasurementTimingBudgetMicroSeconds);
    }

    LOG_FUNCTION_END(Status);
    return Status;
}

