#define KERNEL_OPTS                                                            \
  "init=/bin/sh console=ttyS0  apm=off vsdo=0 reboot=1 "                       \
  "clocksource=kvm-clock noapic initcall_debug=1"

/* A description of the arguments we accept. */
static char args_doc[] = "--image path-to-kernel-image";

/* The options we understand. */
static struct argp_option options[] = {
    {"verbose", 'v', 0, 0, "Produce verbose output"},
    {"memory", 'r', 0, 0, "Ram size for your vm"},
    {"vcpu", 'c', 0, 0, "Number of cpu for your vm"},
    {"image", 'i', "IMAGE", 0, "linux kernel bzimage"},
    {"initramfs", 'z', "PATH", 0, "load initial ram disk"},
    {"kernel-opts", 'k', "OPTIONS", 0, "kernel options"},
    {0}};

/* Used by main to communicate with parse_opt. */
struct arguments {
  int verbose, memory, vcpu;
  char *image_file;
  char *initrd_file;
  char *kernel_opts;
};

/* Parse a single option. */
static error_t parse_opt(int key, char *arg, struct argp_state *state) {
  /* Get the input argument from argp_parse, which we
     know is a pointer to our arguments structure. */
  struct arguments *arguments = state->input;

  switch (key) {
  case 'v':
    arguments->verbose = 1;
    break;
  case 'i':
    arguments->image_file = arg;
    break;
  case 'z':
    arguments->initrd_file = arg;
    break;
  case 'c':
    arguments->vcpu = atoi(arg); /* TODO */
    break;
  case 'r':
    arguments->memory = atoi(arg);
    break;
  case 'k':
    arguments->kernel_opts = arg;
    break;
  default:
    return ARGP_ERR_UNKNOWN;
  }
  return 0;
}

/* Our argp parser. */
static struct argp argp = {options, parse_opt, args_doc, doc};

int main(int argc, char **argv) {

  struct arguments arguments;

  /* Parse our arguments; every option seen by parse_opt will
     be reflected in arguments. */
  argp_parse(&argp, argc, argv, 0, 0, &arguments);

  int ret;
  struct vm core_vm;

  if (arguments.initrd_file != NULL)
    core_vm.initramfs = arguments.initrd_file;

  if (arguments.kernel_opts != NULL)
    core_vm.kernel_opts = arguments.kernel_opts;

  if (arguments.memory != 0)
    core_vm.ram_size = arguments.memory;

  ret = vm_create(&core_vm);
  ERROR(ret)
  ret = vm_init(&core_vm);
  ERROR(ret)

  ret = cpu_create(&core_vm);
  ERROR(ret)
  ret = cpu_setup_cpuid(&core_vm);
  ERROR(ret)
  ret = cpu_mmap(&core_vm);
  ERROR(ret)

  void *ram_address = kernel_load(&core_vm, arguments.image_file);
  ret = cpu_setup_protected_mode(&core_vm);
  ERROR(ret)
  ret = cpu_init_kernel(&core_vm);
  ERROR(ret)
  ret = cpu_main(&core_vm, ram_address);
  ERROR(ret)

  return 0;
}

