    row = 0;
    fprintf(f, "\nint	g2N2tab_ATTLC[] = {  // Cludge\n");
    fprintf(f, "0,");

    for( i = 0; i < 128; i++ ){
	if( i%8 == 0 ){
	    fprintf(f,"\n\n%s\n",g2legend_ATTLC[row++]);
	}
	fprintf(
	    f, 
	    "%d,", 
	    (
		isalpha(i) || 
		i == '_'   || 
		i == '*'   ||         // jfi
		i == '('   ||         // jfi
		i == ')'   ||         // jfi
		isdigit(i)
	    )
	);
	if( i%8 != 7){
	    fprintf(f,"\t");
	}
    }
    fprintf(f, "\n\n/* chars 0200-0377: */");
    for( i = 128; i < 256; i += 8 ){
	fprintf(f, "\n0,\t0,\t0,\t0,\t0,\t0,\t0,\t0,");
    }
