   */
  int back;
  /*
   *   bounds for Stirling number tables
   */
  int maxN;
  int maxM;
  /*
   *  hold out method
   *     hold_every>0 then hold out every n-th in doc
   *     hold_dict>0 then hold out every n-th in dictionary
   *     hold_fraction>0 then hold out final part
