        eui_pkt_settings_t temp_header = { 0 };
        temp_header.internal  = MSG_DEV;
        temp_header.response  = MSG_NRESP;

        eui_send(   auto_output(),
                    find_message_object( msg_id, MSG_DEV ),
                    &temp_header );
    }
}

