int tessMeshTessellateInterior( TESSmesh *mesh )
{
    TESSface *f, *next;

    /*LINTED*/
    for( f = mesh->fHead.next; f != &mesh->fHead; f = next ) {
        /* Make sure we don''t try to tessellate the new triangles. */
        next = f->next;
        if( f->inside ) {
