void TracePC::HandleCallerCallee(uintptr_t Caller, uintptr_t Callee) {
  const PCTableEntry &CallerTE = *PCTableEntryByIdx(Caller);
  const PCTableEntry &CalleeTE = *PCTableEntryByIdx(Callee);
  if (CalleeTE.PCFlags & 1) {
    uintptr_t Idx = PCTableEntryIdx(&CalleeTE);
    if (UseCounters) {
      uint8_t *CounterPtr = &Counters[Idx >> 1];
      uint8_t Counter = (*CounterPtr >> ((Idx & 1) * 4)) & 15;
      if (Counter < 15) {
        *CounterPtr += 1 << ((Idx & 1) * 4);
      }
    }
  }
}

