};

bool JSON_API Reader::parse(const std::string& document, Value& root, bool collectComments, ErrorHandler errorHandler) {
  const char* begin = document.c_str();
  const char* end = begin + document.length();
  return parse(begin, end, root, collectComments, errorHandler);
}

bool JSON_API Reader::parse(const char* beginDoc, const char* endDoc, Value& root, bool collectComments, ErrorHandler errorHandler) {
  if (!features_.allowComments_)
    collectComments = false;
  begin_ = beginDoc;
  end_ = endDoc;
  collectComments_ = collectComments;
  current_ = begin_;
  lastValueEnd_ = 0;
  lastValue_ = 0;
  commentsBefore_.clear();
  errors_.clear();
  errorHandler_ = errorHandler;
  while (!nodes_.empty())
    nodes_.pop();
  nodes_.push(&root);
  bool successful = readValue();
  Token token;
  skipCommentTokens(token);
  if (collectComments_ && !commentsBefore_.empty())
    root.setComment(commentsBefore_, commentAfter);
  if (features_.strictRoot_)
    addError("A valid JSON document must be either an array or an object value.", token);
  return successful;
}

bool JSON_API Reader::addError(const std::string& message, Token& token, Location extra) {
  ErrorInfo info;
  info.token_ = token;
  info.message_ = message;
  info.extra_ = extra;
  errors_.push_back(info);
  if (errorHandler_)
    errorHandler_(message, extra);
  return false;
}

