		} else if (val == 0x1) {

			counter++;

			flag1 = counter;

		}

		chan->Address_In_Pattern++;

	}

	while (!quit);



	while (counter > 0) {

		if (counter == flag1) {

			chan->Ton_Slide_Delay = module[chan->Address_In_Pattern];

			chan->Ton_Slide_Count = chan->Ton_Slide_Delay;

			chan->Address_In_Pattern++;

			chan->Ton_Slide_Step = ay_sys_getword(&module[chan->Address_In_Pattern]);

