        msg->txnid.len = sizeof(uuid_t);
        msg->txnid.data = malloc(sizeof(uuid_t));
        memcpy(msg->txnid.data, ca->txnid, sizeof(uuid_t));
    }
    else
    {
        msg->txnid.data = NULL;
        msg->txnid.len = 0;
    }
    msg->nonce = ca->nonce;
    msg->cell = vcell_msg;
