    sprintf(crt_ptr, "RangeReadQuery(txnid=%s, nonce=%" PRId64 ", start_key=", uuid_str, ca->nonce);
    crt_ptr += strlen(crt_ptr);

    to_string_cell_address(ca->start_cell_address, crt_ptr);
    crt_ptr += strlen(crt_ptr);

    sprintf(crt_ptr, ", end_key=");
    crt_ptr += strlen(crt_ptr);

