    ca->msg_type = QUERY_TYPE_READ_QUEUE_RESPONSE;
    ca->queue_index = new_read_head;
    ca->app_id = app_id;
    ca->shard_id = shard_id;
    ca->consumer_id = consumer_id;
    ca->group_id = group_id;
    ca->cells = cells;
    ca->no_cells = no_cells;
    ca->status = status;
    return ca;

}

